//! Linker arguments for the firmware binaries.
//!
//! `link.x` comes from cortex-m-rt (it includes the `memory.x` generated by
//! embassy-stm32's `memory-x` feature) and `defmt.x` from defmt.

fn main() {
    println!("cargo:rustc-link-arg-bins=--nmagic");
    println!("cargo:rustc-link-arg-bins=-Tlink.x");
    println!("cargo:rustc-link-arg-bins=-Tdefmt.x");
}
